-- Fygle-Solbjørn mast import, 2026-09-16.
-- Source: OPGW_Masteliste_Fygle-Solbjørn_UTM.csv.
-- EPSG:32633 inferred from project map code and verified by channel alignment.
-- Output EPSG:4326. Nearest of ALL masteliste rows by WGS84 ellipsoidal
-- distance (pyproj.Geod); ties resolve by lid then channel.
-- Frozen channel mapping snapshot; intentionally fails if masts already exists.
BEGIN;
CREATE TABLE public.masts (
    id integer PRIMARY KEY,
    mast varchar(32) NOT NULL,
    utmx double precision NOT NULL,
    utmy double precision NOT NULL,
    source_epsg integer NOT NULL DEFAULT 32633 CHECK (source_epsg = 32633),
    latitude double precision NOT NULL CHECK (latitude BETWEEN -90 AND 90),
    longitude double precision NOT NULL CHECK (longitude BETWEEN -180 AND 180),
    lid integer NOT NULL,
    channel integer NOT NULL,
    channel_distance_m double precision NOT NULL CHECK (channel_distance_m >= 0),
    source_file text NOT NULL DEFAULT 'OPGW_Masteliste_Fygle-Solbjørn_UTM.csv',
    imported_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (lid, mast),
    FOREIGN KEY (channel, lid) REFERENCES public.masteliste (channel, lid)
);
COMMENT ON TABLE public.masts IS 'Physical masts in WGS84 (EPSG:4326), matched geographically to the full masteliste channel mapping.';
COMMENT ON COLUMN public.masts.channel IS 'Nearest stored DAS channel ID, not a decimated array index; join using lid and channel.';
COMMENT ON COLUMN public.masts.channel_distance_m IS 'WGS84 ellipsoidal distance to nearest channel at import. Large distances can indicate masts beyond mapped coverage.';
COMMENT ON COLUMN public.masts.source_epsg IS 'Source CRS inferred as WGS84 / UTM zone 33N from project code and spatial alignment; CSV has no CRS declaration.';
COPY public.masts (id,mast,utmx,utmy,latitude,longitude,lid,channel,channel_distance_m) FROM stdin WITH CSV;
